+const ALLOWED_FIELDS = ['order_id', 'include_history'];
+
+/**
+ * List the tools exposed by this MCP server.
+ * @returns {Promise<Array>} MCP tool descriptors.
+ */
+export async function listTools() {
+  return [
+    {
+      name: 'order_status',
+      title: 'Order Status',
+      description:
+        'Get the current status of an order by its unique order ID. ' +
+        'Optionally include the full chronological status history for the order.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          order_id: {
+            type: 'string',
+            description: 'The unique identifier of the order to look up.'
+          },
+          include_history: {
+            type: 'boolean',
+            default: false,
+            description:
+              'When true, include the chronological status history for the order. Defaults to false.'
+          }
+        },
+        required: ['order_id'],
+        additionalProperties: false
+      },
+      annotations: {
+        readOnlyHint: true,
+        destructiveHint: false,
+        idempotentHint: true,
+        openWorldHint: false
+      }
+    }
+  ];
+}
+
+/**
+ * Validate arguments for the order_status tool.
+ * @param {unknown} args - Raw arguments passed to the tool.
+ * @returns {{order_id:string, include_history:boolean}} Validated arguments.
+ * @throws {Error} when fields are missing, wrong type, or unexpected.
+ */
+function validateArgs(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object.');
+  }
+
+  const extra = Object.keys(args).filter((k) => !ALLOWED_FIELDS.includes(k));
+  if (extra.length > 0) {
+    throw new Error(
+      `Invalid arguments: unexpected field(s): ${extra.join(', ')}. ` +
+        `Allowed fields are: ${ALLOWED_FIELDS.join(', ')}.`
+    );
+  }
+
+  if (!('order_id' in args)) {
+    throw new Error('Invalid arguments: order_id is required.');
+  }
+  const { order_id, include_history = false } = args;
+
+  if (typeof order_id !== 'string') {
+    throw new Error('Invalid arguments: order_id must be a string.');
+  }
+  if (typeof include_history !== 'boolean') {
+    throw new Error('Invalid arguments: include_history must be a boolean.');
+  }
+
+  return { order_id, include_history };
+}
+
+/**
+ * Invoke a tool by name with the given arguments.
+ * @param {string} name - Tool name.
+ * @param {unknown} [args] - Tool arguments.
+ * @returns {Promise<{content:Array<{type:string,text:string}>}>} Tool result.
+ * @throws {Error} for unknown tools, invalid arguments, or missing orders.
+ */
+export async function callTool(name, args = {}) {
+  if (name !== 'order_status') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const { order_id, include_history } = validateArgs(args);
+
+  const order = orders[order_id];
+  if (!order) {
+    throw new Error(`Order not found: ${order_id}`);
+  }
+
+  const result = { order_id, status: order.status };
+  if (include_history) {
+    // History is stored chronologically; return a copy in that order.
